import React from 'react';
import { useOutletContext } from 'react-router-dom';
import RealtimeWorkspace from '../../components/RealtimeWorkspace';
import ProjectNavbar from '../../components/ProjectNavbar';

const WorkspacePage = () => {
  // 1. Fetch the multi-module global layout context hub safely
  const context = useOutletContext();
  
  // 2. Extract the dedicated channel for the Workspace module from our partitioned state silo
  const { data: workspaceData, setter: setWorkspaceData } = context?.work || {};

  return (
    <div className="h-full">
      {/* Module-level navigation sub-tabs */}
      <ProjectNavbar 
        basePath="work" 
        links={["Streaming", "Collab", "Nodes", "Logs"]} 
      />
      
      <div className="p-8">
         {/* 3. Pass down data and state hooks directly to the nested workspace canvas engine */}
         <RealtimeWorkspace 
           workspaceData={workspaceData} 
           setWorkspaceData={setWorkspaceData} 
           layoutContext={context}
         />
      </div>
    </div>
  );
};

export default WorkspacePage;
